DROP VIEW IF EXISTS current_document_party_links;
ALTER TABLE document_party_link_events RENAME TO document_party_link_events_v26;
CREATE TABLE document_party_link_events (
 id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES documents(id), party_id TEXT NOT NULL CHECK(length(party_id) BETWEEN 3 AND 64),
 party_role TEXT NOT NULL CHECK(party_role IN ('issuer','supplier','customer','recipient','payer','payee','processor','acquirer','related_company','establishment','location','payment_descriptor','vendor','owner','adviser','employee','authority','bank')),
 event_type TEXT NOT NULL CHECK(event_type IN ('linked','superseded')), evidence_kind TEXT NOT NULL CHECK(evidence_kind IN ('exact_identifier','reviewed_legacy_reference')), evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)), document_sha256 TEXT NOT NULL CHECK(length(document_sha256)=64), document_payload_sha256 TEXT NOT NULL CHECK(length(document_payload_sha256)=64), party_snapshot_json TEXT NOT NULL CHECK(json_valid(party_snapshot_json)), plan_hash TEXT NOT NULL CHECK(length(plan_hash)=64), idempotency_key TEXT, reason TEXT, actor TEXT NOT NULL, principal TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(document_id, party_role, event_type, plan_hash), UNIQUE(idempotency_key)
);
INSERT INTO document_party_link_events SELECT * FROM document_party_link_events_v26;
DROP TABLE document_party_link_events_v26;
CREATE VIEW current_document_party_links AS SELECT e.* FROM document_party_link_events e WHERE e.event_type='linked' AND NOT EXISTS (SELECT 1 FROM document_party_link_events s WHERE s.event_type='superseded' AND s.document_id=e.document_id AND s.party_role=e.party_role AND s.plan_hash=e.plan_hash);
CREATE INDEX document_party_link_events_document ON document_party_link_events(document_id,party_role,id);
CREATE TRIGGER document_party_link_events_no_update BEFORE UPDATE ON document_party_link_events BEGIN SELECT RAISE(ABORT, 'document party link events are append-only'); END;
CREATE TRIGGER document_party_link_events_no_delete BEFORE DELETE ON document_party_link_events BEGIN SELECT RAISE(ABORT, 'document party link events are append-only'); END;
CREATE TABLE document_party_resolution_events (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES documents(id), state TEXT NOT NULL CHECK(state IN ('internal_no_external_party','superseded')), reason TEXT NOT NULL, document_sha256 TEXT NOT NULL CHECK(length(document_sha256)=64), document_payload_sha256 TEXT NOT NULL CHECK(length(document_payload_sha256)=64), decision_hash TEXT NOT NULL CHECK(length(decision_hash)=64), supersedes_hash TEXT, idempotency_key TEXT UNIQUE, actor TEXT NOT NULL, principal TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(document_id,state,decision_hash));
CREATE VIEW current_document_party_resolution_events AS SELECT e.* FROM document_party_resolution_events e WHERE e.state='internal_no_external_party' AND NOT EXISTS (SELECT 1 FROM document_party_resolution_events s WHERE s.state='superseded' AND s.document_id=e.document_id AND s.supersedes_hash=e.decision_hash);
CREATE TRIGGER document_party_resolution_events_no_update BEFORE UPDATE ON document_party_resolution_events BEGIN SELECT RAISE(ABORT, 'document party resolution events are append-only'); END;
CREATE TRIGGER document_party_resolution_events_no_delete BEFORE DELETE ON document_party_resolution_events BEGIN SELECT RAISE(ABORT, 'document party resolution events are append-only'); END;
